<script lang="ts">import { T } from '@threlte/core';
import { Object3D } from 'three';
let { parent, children } = $props();
const object = new Object3D();
object.add = (child) => {
    return parent.add(child);
};
object.remove = (child) => {
    return parent.remove(child);
};
</script>

<T is={object} attach={false}>
	{@render children?.()}
</T>
